// WF-5 guard — validate state.candidate and build sandbox payload
const state = $input.first().json;
if (!state || state.schema_version !== 1) throw new Error('bad');
const candidate = state.candidate;
if (!candidate || !candidate.code) throw new Error('no candidate');
let toolInput = state._toolInput || '';
if (!toolInput) {
  const g = state.goal || '';
  const m = g.match(/'([^']{10,})'/);
  if (m) toolInput = m[1];
  else toolInput = g;
}
return [{ json: {
  code: candidate.code,
  input: toolInput,
  language: candidate.language || 'python',
  timeout_s: 10,
  memory_mb: 256,
  _state: state
}}];

// WF-5 normalize — map sandbox response back into state.test
const sandbox = $input.first().json;
const prev = $('Guard: validate state → sandbox payload').first().json._state;
// sandbox runner returns {stdout, stderr, exit_code, duration_ms, timed_out}
const passed = sandbox.exit_code === 0 && !sandbox.timed_out;
const run = {
  input: $('Guard: validate state → sandbox payload').first().json.input,
  stdout: sandbox.stdout || '',
  stderr: sandbox.stderr || '',
  exit_code: sandbox.exit_code ?? -1,
  duration_ms: sandbox.duration_ms ?? 0
};
// thread back into state
const next = JSON.parse(JSON.stringify(prev));
next.test = next.test || { passed: false, runs: [] };
next.test.passed = passed;
next.test.runs = (next.test.runs || []).concat([run]);
// also set outcome.final_answer for walking skeleton convenience
if (passed) {
  next.outcome = next.outcome || {};
  next.outcome.final_answer = (sandbox.stdout || '').trim();
  // keep status as deployed for now — WF-4/Orchestrator will set deployed/reused
}
return [{ json: next }];
